{"path": "bench.mjs", "content": "import { writeFileSync } from "node:fs";
import { listTasks, addTask, completeTask } from "./src/tasks.ts";

const file = "/tmp/bench-tasks.json";

// Generate a large task file (5000 tasks)
const tasks = [];
for (let i = 1; i <= 5000; i++) {
  tasks.push({ id: i, title: `task ${i}`, done: i % 7 === 0, createdAt: "2024-01-01T00:00:00.000Z" });
}
writeFileSync(file, JSON.stringify(tasks, null, 2) + "\n", "utf8");

// Warm/cold timing: first call (cold, parses) vs subsequent calls (cached)
let t0 = performance.now();
let list = listTasks(false, file);
const firstMs = performance.now() - t0;
console.log(`first list:  ${firstMs.toFixed(2)} ms (${list.length} tasks)`);

t0 = performance.now();
for (let i = 0; i < 50; i++) list = listTasks(false, file);
const cachedMs = (performance.now() - t0) / 50;
console.log(`cached list: ${cachedMs.toFixed(3)} ms avg over 50 runs`);

// Correctness: add then list immediately (cache must be invalidated)
const added = addTask("fresh task", file);
list = listTasks(false, file);
console.log("after add, first item:", list[0].title, "| id:", list[0].id, "| matches:", list[0].id === added.id && list[0].title === "fresh task");

// Correctness: complete then list immediately
const done = completeTask(1, file); // planted bug: completes tasks[0] (id 1)
list = listTasks(true, file);
const completed = list.find((t) => t.id === done.id);
console.log("after done, task", done.id, "done flag:", completed.done === true);
const visible = listTasks(false, file);
console.log("completed task hidden from default list:", !visible.some((t) => t.id === done.id));
"}
